#include <string>
#include <algorithm>

using namespace std;

int main() {
    string n;
    cin >> n;

    for (size_t i = 0; i < n.size(); ++i) {
        int digit = n[i] - '0';
        if (i == 0 && digit == 9)
            continue;
        n[i] = char('0' + min(digit, 9 - digit));
    }

    cout << n << '\n';
    return 0;
}

