    for (size_t i = 0; i < n.size(); ++i) {
        int digit = n[i] - '0';
        int inverted = 9 - digit;

        if (inverted < digit && !(i == 0 && inverted == 0))
            n[i] = char('0' + inverted);
    }

    cout << n << '\n';
    return 0;
